// The data files the page loads as scripts (generated by tools/, one global each).

// ---- platforms.js (tools/build_platforms.py): every platform and stop edge in Switzerland ----

/** How a stop is served: train, tram / metro, bus, ship, cable car. */
type PlatformModeCode = 't' | 'm' | 'b' | 's' | 'c';
/**
 * One platform or stop edge: longitude and latitude × 100 000, its name ("7", "H"; '' when it has none), the
 * compass direction vehicles stop in, and the floor when it is not at street level. Trailing values may be missing.
 */
type PlatformDataEdge = [lonE5: number, latE5: number, ref?: string, bearing?: number | null, level?: number | null];
/** A stop: its name, how it is served, its edges. */
type PlatformDataStop = [name: string, mode: PlatformModeCode, edges: PlatformDataEdge[]];
interface PlatformData {
  /** The day the file was built, "2026-11-21". */
  date: string;
  /** By UIC number ("8507000"). */
  stops: Record<string, PlatformDataStop>;
}
/** Loaded on demand; src/app/30-platforms.ts deletes it again once it has indexed it. */
declare var PLATFORM_DATA: PlatformData | undefined;

// ---- bern-events.js, swiss-workshops.js, community-programmes.js: community events (src/events.ts joins them) ----

/** Events of Bern-area calendars, one listing per date. */
declare var BERN_EVENTS: EventListing[];
/** Workshops and regular meetings all over Switzerland. */
declare var SWISS_WORKSHOPS: EventListing[];
/** Events with several dates: the event once, with its dates as `sessions`. */
declare var SWISS_EVENT_SERIES: EventSeries[];
/** Local programmes (language courses, sport clubs, …); some are known by their town only (`areaOnly`). */
declare var COMMUNITY_PROGRAMMES: EventListing[];

// ---- map-places.js (tools/build-map-places.mjs): toilets, drinking water, health, help, shops… ----

/** What is known about a place besides its name. Every field may be missing. */
interface MapPlaceDetails {
  /** Address: 'Neuengasse 15, 3011 Bern'. */
  a?: string;
  /** Opening hours as OpenStreetMap writes them ('Mo-Fr 08:00-17:00'); '24/7' = day and night. */
  h?: string;
  /** Wheelchair: getting to the place. */
  w?: 'yes' | 'limited' | 'no';
  /** Toilets: is there one for wheelchair users. */
  tw?: 'yes' | 'limited' | 'no';
  /** Fee: 'mixed' = a free and a paying toilet at the same site. */
  f?: 'no' | 'yes' | 'mixed';
  /** Price: 'CHF 1.00'. */
  pr?: string;
  /** What the fee is for, in the source's words. */
  ft?: string;
  /** Phone. */
  p?: string;
  /** Website. */
  u?: string;
  /** Floor: '0', '-1', '2;3'. */
  l?: string;
  /** Description. */
  d?: string;
  /** Who may use it; 'unsure' = it may be shut or locked. Missing: everyone. */
  k?: 'customers' | 'private' | 'permissive' | 'permit' | 'key' | 'wheelchair' | 'unsure';
  /** 1 = has a changing table. */
  c?: 1;
  /** 1 = opens with a Eurokey. */
  e?: 1;
  /** Run by. */
  o?: string;
  /** Index into MapPlaces.sources; missing = 0 (OpenStreetMap). */
  s?: number;
}
/** One place: where, its category (an index into MapPlaces.cats), its name (0 when it has none), and details when there are any. */
type MapPlaceRow = [lon: number, lat: number, category: number, name: string | 0, details?: MapPlaceDetails];
interface MapPlaces {
  /** When the data was fetched (ISO date and time). */
  generated: string;
  /** Who the data comes from: 'OpenStreetMap', 'Stadt Bern', … */
  sources: string[];
  /** The kinds of place, each as MAP_LAYERS.classify() gives it. */
  cats: PlaceClass[];
  items: MapPlaceRow[];
}
/** Loaded on demand; src/app/32-places.ts deletes it again once it has taken the data. */
declare var MAP_PLACES: MapPlaces | undefined;
